/* The Coverage schema: every kind of object and column the Sharp Factory schema reader handles.
   Tests/SF.Tests/Fixtures/Coverage.edmj is its model. Structure only; run once in a test database
   (fails if the Coverage schema already exists). */

CREATE SCHEMA Coverage
GO

/* every SQL Server column type, identity, defaults, rowversion, computed columns */
CREATE TABLE Coverage.AllTypes (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_AllTypes PRIMARY KEY,
    BigIntCol bigint NOT NULL,
    BigIntNull bigint NULL,
    BinaryCol binary(16) NULL,
    BitCol bit NOT NULL CONSTRAINT DF_AllTypes_BitCol DEFAULT (0),
    CharCol char(10) NULL,
    DateCol date NULL,
    DateTimeCol datetime NOT NULL CONSTRAINT DF_AllTypes_DateTimeCol DEFAULT (GETDATE()),
    DateTime2Col datetime2(7) NULL,
    DateTimeOffsetCol datetimeoffset(7) NULL,
    DecimalCol decimal(18,4) NOT NULL CONSTRAINT DF_AllTypes_DecimalCol DEFAULT (1.5),
    FloatCol float NULL,
    HierarchyIdCol hierarchyid NULL,
    ImageCol image NULL,
    IntNull int NULL,
    MoneyCol money NULL,
    NCharCol nchar(10) NULL,
    NTextCol ntext NULL,
    NumericCol numeric(10,2) NULL,
    NVarCharCol nvarchar(50) NOT NULL CONSTRAINT DF_AllTypes_NVarCharCol DEFAULT (N'default text'),
    NVarCharMaxCol nvarchar(max) NULL,
    RealCol real NULL,
    SmallDateTimeCol smalldatetime NULL,
    SmallIntCol smallint NULL,
    SmallMoneyCol smallmoney NULL,
    SqlVariantCol sql_variant NULL,
    SysNameCol sysname NULL,
    TextCol text NULL,
    TimeCol time(7) NULL,
    TinyIntCol tinyint NULL,
    GuidCol uniqueidentifier NOT NULL CONSTRAINT DF_AllTypes_GuidCol DEFAULT (NEWID()),
    VarBinaryCol varbinary(50) NULL,
    VarBinaryMaxCol varbinary(max) NULL,
    VarCharCol varchar(50) NULL,
    VarCharMaxCol varchar(max) NULL,
    XmlCol xml NULL,
    GeographyCol geography NULL,
    GeometryCol geometry NULL,
    RowVersionCol rowversion NOT NULL,
    ComputedCol AS (DecimalCol * 2),
    PersistedComputedCol AS (CONVERT(nvarchar(20), Id)) PERSISTED
)
GO

/* a varbinary default longer than 4000 characters (the reader re-reads it from sys.columns) */
CREATE TABLE Coverage.LongDefault (
    Id int NOT NULL CONSTRAINT PK_LongDefault PRIMARY KEY,
    Blob varbinary(max) NOT NULL CONSTRAINT DF_LongDefault_Blob DEFAULT ()
)
GO

/* composite primary key, composite unique key, two-column foreign key */
CREATE TABLE Coverage.Region (
    CountryCode char(2) NOT NULL,
    RegionCode varchar(10) NOT NULL,
    Name nvarchar(100) NOT NULL,
    CONSTRAINT PK_Region PRIMARY KEY (CountryCode, RegionCode),
    CONSTRAINT UK_Region_Name UNIQUE (CountryCode, Name)
)
GO
CREATE TABLE Coverage.Store (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Store PRIMARY KEY,
    CountryCode char(2) NOT NULL,
    RegionCode varchar(10) NOT NULL,
    Name nvarchar(100) NOT NULL,
    CONSTRAINT FK_Store_Region FOREIGN KEY (CountryCode, RegionCode) REFERENCES Coverage.Region (CountryCode, RegionCode)
)
GO

/* self-referencing foreign key */
CREATE TABLE Coverage.Employee (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Employee PRIMARY KEY,
    ManagerId int NULL CONSTRAINT FK_Employee_Manager REFERENCES Coverage.Employee (Id),
    Name nvarchar(100) NOT NULL
)
GO

/* one-to-one: through the child's primary key, and through a unique key */
CREATE TABLE Coverage.Person (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Person PRIMARY KEY,
    Name nvarchar(100) NOT NULL
)
GO
CREATE TABLE Coverage.PersonDetail (
    PersonId int NOT NULL CONSTRAINT PK_PersonDetail PRIMARY KEY CONSTRAINT FK_PersonDetail_Person REFERENCES Coverage.Person (Id),
    Notes nvarchar(max) NULL
)
GO
CREATE TABLE Coverage.Passport (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Passport PRIMARY KEY,
    PersonId int NOT NULL CONSTRAINT UK_Passport_Person UNIQUE CONSTRAINT FK_Passport_Person REFERENCES Coverage.Person (Id),
    Number varchar(20) NOT NULL
)
GO

/* two foreign keys to the same table */
CREATE TABLE Coverage.Warehouse (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Warehouse PRIMARY KEY,
    Name nvarchar(100) NOT NULL
)
GO
CREATE TABLE Coverage.Shipment (
    Id bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Shipment PRIMARY KEY,
    FromWarehouseId int NOT NULL CONSTRAINT FK_Shipment_FromWarehouse REFERENCES Coverage.Warehouse (Id),
    ToWarehouseId int NOT NULL CONSTRAINT FK_Shipment_ToWarehouse REFERENCES Coverage.Warehouse (Id),
    ShippedOn datetime2(7) NULL
)
GO

/* names that need cleaning */
CREATE TABLE Coverage.[Order Line] (
    Id int IDENTITY(1,1) NOT NULL CONSTRAINT [PK_Order Line] PRIMARY KEY,
    [2ndValue] int NULL,
    Unit_Price money NULL,
    Item_No nvarchar(20) NULL,
    Size_cm decimal(9,2) NULL,
    [_Underscore] int NULL,
    Weight_Kg decimal(9,3) NULL
)
GO

/* a table named like its schema, a column named like its table, a plural table name */
CREATE TABLE Coverage.Coverage (
    Id int NOT NULL CONSTRAINT PK_Coverage PRIMARY KEY,
    Note nvarchar(50) NULL
)
GO
CREATE TABLE Coverage.Status (
    Id int NOT NULL CONSTRAINT PK_Status PRIMARY KEY,
    Status nvarchar(20) NOT NULL
)
GO
CREATE TABLE Coverage.Categories (
    Id int NOT NULL CONSTRAINT PK_Categories PRIMARY KEY,
    Name nvarchar(50) NOT NULL
)
GO

/* a table without a primary key */
CREATE TABLE Coverage.AuditLog (
    LoggedAt datetime2(7) NOT NULL CONSTRAINT DF_AuditLog_LoggedAt DEFAULT (SYSUTCDATETIME()),
    Message nvarchar(400) NOT NULL
)
GO

/* trigger */
CREATE TRIGGER Coverage.TR_Employee_Audit ON Coverage.Employee AFTER INSERT, UPDATE AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO Coverage.AuditLog (Message) SELECT CONCAT(N'Employee changed: ', i.Id) FROM inserted i;
END
GO

/* views */
CREATE VIEW Coverage.EmployeeDirectory AS
    SELECT e.Id, e.Name, m.Name AS ManagerName
    FROM Coverage.Employee e LEFT JOIN Coverage.Employee m ON m.Id = e.ManagerId
GO
CREATE VIEW Coverage.StoreRegions AS
    SELECT s.Id, s.Name, r.Name AS RegionName, r.CountryCode
    FROM Coverage.Store s JOIN Coverage.Region r ON r.CountryCode = s.CountryCode AND r.RegionCode = s.RegionCode
GO

/* functions: scalar, inline table, multi-statement table */
CREATE FUNCTION Coverage.ShipmentCount (@WarehouseId int) RETURNS int AS
BEGIN
    RETURN (SELECT COUNT(*) FROM Coverage.Shipment WHERE FromWarehouseId = @WarehouseId);
END
GO
CREATE FUNCTION Coverage.FullName (@First nvarchar(50), @Last nvarchar(50)) RETURNS nvarchar(101) AS
BEGIN
    RETURN CONCAT(@First, N' ', @Last);
END
GO
CREATE FUNCTION Coverage.ShipmentsFrom (@WarehouseId int) RETURNS TABLE AS
    RETURN (SELECT Id, ToWarehouseId, ShippedOn FROM Coverage.Shipment WHERE FromWarehouseId = @WarehouseId)
GO
CREATE FUNCTION Coverage.EmployeesUnder (@ManagerId int) RETURNS @result TABLE (Id int NOT NULL, Name nvarchar(100) NOT NULL) AS
BEGIN
    INSERT INTO @result SELECT Id, Name FROM Coverage.Employee WHERE ManagerId = @ManagerId;
    RETURN;
END
GO

/* sequences */
CREATE SEQUENCE Coverage.InvoiceNumber AS bigint START WITH 1000 INCREMENT BY 1
GO
CREATE SEQUENCE Coverage.TicketNumber AS int START WITH 1 INCREMENT BY 1
GO

/* stored procedures: result set, optional parameter, OUTPUT parameter, no result set, temp table (forces the reader's fallback path) */
CREATE PROCEDURE Coverage.GetEmployees AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, Name, ManagerId FROM Coverage.Employee;
END
GO
CREATE PROCEDURE Coverage.GetShipments @FromWarehouseId int, @Since datetime2(7) = NULL AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, ToWarehouseId, ShippedOn FROM Coverage.Shipment WHERE FromWarehouseId = @FromWarehouseId AND (@Since IS NULL OR ShippedOn >= @Since);
END
GO
CREATE PROCEDURE Coverage.CountShipments @WarehouseId int, @Total int OUTPUT AS
BEGIN
    SET NOCOUNT ON;
    SELECT @Total = COUNT(*) FROM Coverage.Shipment WHERE FromWarehouseId = @WarehouseId;
END
GO
CREATE PROCEDURE Coverage.TouchEmployee @Id int AS
BEGIN
    SET NOCOUNT ON;
    UPDATE Coverage.Employee SET Name = Name WHERE Id = @Id;
END
GO
CREATE PROCEDURE Coverage.UsesTempTable AS
BEGIN
    SET NOCOUNT ON;
    CREATE TABLE #t (Id int);
    INSERT INTO #t VALUES (1);
    SELECT Id FROM #t;
END
GO
